'use client';
/**
 * Community gallery with filters. The FLIP-grid-reorder pattern, rebuilt on the motion module's `flip()` for this
 * page's own entries: tiles that stay glide to their new cells, leaving tiles are removed at once, entering tiles
 * fade and scale in. DOM order always equals reading order. Reduced motion: no glide, entering tiles fade in 160 ms.
 */
import { useEffect, useRef, useState } from 'react';
import { flushSync } from 'react-dom';
import { duration as D, flip, useStudioMotion } from '../../../motion';
import { CATEGORIES, ENTRIES, type Category } from './data';
import { MendMotif } from './motifs';
import styles from './styles.module.css';

type Filter = Category | 'All';

export function Gallery() {
  const { reduced } = useStudioMotion();
  const [filter, setFilter] = useState<Filter>('All');
  const grid = useRef<HTMLUListElement>(null);
  const anims = useRef(new Set<Animation>());
  useEffect(() => { const set = anims.current; return () => { set.forEach((a) => a.cancel()); set.clear(); }; }, []);

  const track = (a: Animation) => {
    anims.current.add(a);
    const done = () => anims.current.delete(a);
    a.finished.then(done, done);
  };

  const choose = (next: Filter) => {
    if (next === filter) return;
    const el = grid.current;
    anims.current.forEach((a) => a.cancel());
    anims.current.clear();
    if (!el) { setFilter(next); return; }
    const tiles = Array.from(el.querySelectorAll<HTMLElement>('[data-tile]'));
    const before = new Set(tiles.filter((t) => !t.hidden));
    flip(before, () => flushSync(() => setFilter(next)), { duration: D.moderate, easing: 'emphasized', reducedMotion: reduced }).forEach(track);
    tiles.filter((t) => !t.hidden && !before.has(t)).forEach((t, i) => {
      if (typeof t.animate !== 'function') return;
      track(t.animate(
        reduced ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 0, transform: 'scale(0.92)' }, { opacity: 1, transform: 'none' }],
        { duration: reduced ? D.fast : D.moderate, delay: reduced ? 0 : 80 + i * 36, easing: 'cubic-bezier(0.16, 1, 0.3, 1)', fill: 'backwards' },
      ));
    });
  };

  const shown = ENTRIES.filter((e) => filter === 'All' || e.category === filter).length;
  return (
    <div>
      <div className={styles.filters} role="group" aria-label="Show mends by kind">
        {(['All', ...CATEGORIES] as const).map((c) => (
          <button key={c} type="button" className={styles.chip} aria-pressed={filter === c} onClick={() => choose(c)}>{c}</button>
        ))}
      </div>
      <p className={styles.count} aria-live="polite">Showing {shown} of {ENTRIES.length} mends{filter === 'All' ? '' : ` · ${filter}`}</p>
      <ul ref={grid} className={styles.grid}>
        {ENTRIES.map((e) => (
          <li key={e.id} data-tile="" className={styles.tile} hidden={filter !== 'All' && e.category !== filter}>
            <div role="img" aria-label={e.alt} className={styles.tileArt}><MendMotif motif={e.motif} /></div>
            <p className={styles.tileTitle}>{e.title}</p>
            <p className={styles.tileMeta}>{e.who} · {e.where}</p>
            <span className={styles.tileTag}>{e.category}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

'use client';
/**
 * Café leaderboard — the bar-race pattern, rebuilt with CSS transforms for this page's own (sample) data: rows
 * slide to their new rank and bars grow on ONE shared scale. The drawing is aria-hidden; an ordered list in rank
 * order carries the same numbers for assistive tech. Play steps through the four weeks once (under 5 s) and can be
 * paused; reduced motion swaps each week in without sliding or growing.
 */
import { useEffect, useId, useRef, useState } from 'react';
import { CAFES, WEEKLY } from './data';
import styles from './styles.module.css';

const ROW = 48;
const STEP_MS = 1150;
const MAX = Math.max(...Object.values(WEEKLY).flat());

export function Leaderboard() {
  const uid = useId();
  const [week, setWeek] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [say, setSay] = useState('');
  const weekRef = useRef(week);
  weekRef.current = week;
  const touched = useRef(false); // announce only after the person has used the controls

  const ranked = [...CAFES].sort((a, b) => WEEKLY[b][week] - WEEKLY[a][week]);
  const rank = new Map(ranked.map((c, i) => [c, i]));
  const describe = (w: number) => {
    const top = [...CAFES].sort((a, b) => WEEKLY[b][w] - WEEKLY[a][w])[0];
    return `Week ${w + 1}: ${top} has logged the most so far, ${WEEKLY[top][w]} items.`;
  };

  useEffect(() => {
    if (!playing) return;
    const t = setInterval(() => {
      const next = Math.min(3, weekRef.current + 1);
      setWeek(next);
      if (next >= 3) setPlaying(false);
    }, STEP_MS);
    return () => clearInterval(t);
  }, [playing]);
  useEffect(() => { if (!playing && touched.current) setSay(describe(week)); }, [playing, week]); // eslint-disable-line react-hooks/exhaustive-deps

  const play = () => {
    touched.current = true;
    if (playing) { setPlaying(false); return; }
    if (week >= 3) setWeek(0);
    setPlaying(true);
  };

  return (
    <div className={styles.board}>
      <div className={styles.boardControls}>
        <button type="button" className={styles.playBtn} aria-pressed={playing} onClick={play}>
          {playing
            ? <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M5 3v10M11 3v10" /></svg>
            : <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M5 3l8 5-8 5z" className={styles.solid} /></svg>}
          {playing ? 'Pause' : week >= 3 ? 'Replay March' : 'Play March'}
        </button>
        <fieldset className={styles.weeks}>
          <legend className="s3-sr-only">Show week</legend>
          {[0, 1, 2, 3].map((w) => (
            <label key={w} className={styles.week}>
              <input type="radio" name={`${uid}-week`} checked={week === w} onChange={() => { touched.current = true; setPlaying(false); setWeek(w); }} />
              <span>Week {w + 1}</span>
            </label>
          ))}
        </fieldset>
      </div>

      <div className={styles.race} style={{ height: ROW * CAFES.length }} aria-hidden="true">
        {CAFES.map((c) => {
          const value = WEEKLY[c][week];
          const r = rank.get(c) ?? 0;
          return (
            <div key={c} className={styles.raceRow} data-lead={r === 0 || undefined} style={{ transform: `translateY(${r * ROW}px)` }}>
              <span className={styles.raceRank}>{r + 1}</span>
              <span className={styles.raceName}>{c}</span>
              <span className={styles.raceTrack}><span className={styles.raceBar} style={{ transform: `scaleX(${value / MAX})` }} /></span>
              <span className={styles.raceValue}>{value}</span>
            </div>
          );
        })}
      </div>
      <ol className="s3-sr-only" aria-label={`Cafés ranked by items logged, week ${week + 1} of March 2026 (sample data)`}>
        {ranked.map((c) => <li key={c}>{c}: {WEEKLY[c][week]} items</li>)}
      </ol>
      <p className="s3-sr-only" aria-live="polite">{say}</p>
    </div>
  );
}

'use client';
/**
 * The participation flow: pledge one mend. Errors appear on blur (once a field was touched) and on submit, with
 * aria-invalid + aria-describedby; a failed submit moves focus to the first problem. Nothing personal is required
 * (the name is optional), showing the entry in the gallery is opt-in, and nothing leaves the page.
 */
import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { duration as D, useStudioMotion } from '../../../motion';
import { CAFES, CATEGORIES } from './data';
import styles from './styles.module.css';

export interface Pledge { item: string; category: string; where: string; name: string; gallery: boolean }
type Field = 'item' | 'category' | 'where' | 'name';
const ORDER: Field[] = ['item', 'category', 'where', 'name'];

function validate(v: Pledge): Partial<Record<Field, string>> {
  const e: Partial<Record<Field, string>> = {};
  const item = v.item.trim();
  if (item.length < 3) e.item = item ? 'A few more letters, please — at least 3.' : 'Tell us the one thing you will mend.';
  else if (item.length > 60) e.item = 'Keep it under 60 characters so it fits the share card.';
  if (!v.category) e.category = 'Choose what kind of thing it is.';
  if (!v.where) e.where = 'Choose a café, or “At home”.';
  if (v.name.trim().length > 40) e.name = 'Keep the name under 40 characters.';
  return e;
}

export function PledgeForm({ onPledged, onEdit }: { onPledged: (p: Pledge) => void; onEdit: () => void }) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const [v, setV] = useState<Pledge>({ item: '', category: '', where: '', name: '', gallery: false });
  const [touched, setTouched] = useState<Partial<Record<Field, boolean>>>({});
  const [tried, setTried] = useState(false);
  const [status, setStatus] = useState<'idle' | 'sending' | 'done'>('idle');
  const [say, setSay] = useState('');
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const doneHead = useRef<HTMLHeadingElement>(null);
  const check = useRef<SVGPathElement>(null);
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);

  const errors = validate(v);
  const show = (f: Field) => (tried || touched[f]) && errors[f];
  const id = (s: string) => `${uid}-${s}`;
  const set = <K extends keyof Pledge>(k: K, val: Pledge[K]) => setV((p) => ({ ...p, [k]: val }));
  const described = (f: Field, hint?: boolean) => [hint ? id(`${f}-hint`) : '', show(f) ? id(`${f}-err`) : ''].filter(Boolean).join(' ') || undefined;

  useEffect(() => {
    if (status !== 'done') return;
    doneHead.current?.focus();
    const p = check.current;
    if (!p || reduced || typeof p.animate !== 'function') return;
    const a = p.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: D.slow, easing: 'cubic-bezier(0.16, 1, 0.3, 1)' });
    return () => a.cancel();
  }, [status, reduced]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (status === 'sending') return;
    setTried(true);
    const bad = ORDER.filter((f) => errors[f]);
    if (bad.length) {
      setSay(`${bad.length === 1 ? 'One answer needs' : `${bad.length} answers need`} attention.`);
      const first = bad[0];
      const target = first === 'category' ? document.querySelector<HTMLInputElement>(`input[name="${id('category')}"]`) : document.getElementById(id(first));
      target?.focus();
      return;
    }
    setStatus('sending');
    setSay('Saving your pledge…');
    timer.current = setTimeout(() => { setStatus('done'); setSay(''); onPledged({ ...v, item: v.item.trim(), name: v.name.trim() }); }, 700);
  };

  if (status === 'done') {
    return (
      <div className={styles.done}>
        <svg viewBox="0 0 64 64" className={styles.doneMark} aria-hidden="true" focusable="false">
          <rect x="6" y="6" width="52" height="52" rx="4" className={styles.donePatch} />
          <path ref={check} d="M18 33l10 10 18-22" pathLength={1} className={styles.doneCheck} />
        </svg>
        <h3 ref={doneHead} tabIndex={-1} className={styles.doneTitle}>Pledged: {v.item.trim()}</h3>
        <p>
          See you in March. Mend it {v.where === 'At home' ? 'at home' : `at ${v.where}`} any day from 1 to 31 March 2027
          {v.gallery ? ', and your before-and-after can go in the gallery.' : '. Your pledge stays out of the gallery, as you chose.'}
        </p>
        <p className={styles.small}>Demo: nothing was sent or stored. Edit it, or make a share card below.</p>
        <button type="button" className={styles.ghost} onClick={() => { setStatus('idle'); onEdit(); }}>Edit pledge</button>
      </div>
    );
  }

  return (
    <form className={styles.form} onSubmit={submit} noValidate aria-describedby={id('privacy')}>
      <div className={styles.field}>
        <label htmlFor={id('item')} className={styles.label}>What will you mend?</label>
        <p id={id('item-hint')} className={styles.small}>One thing is plenty: a jumper, a lamp, a wobbly chair.</p>
        <input id={id('item')} className={styles.input} value={v.item} maxLength={80} autoComplete="off"
          aria-invalid={show('item') ? true : undefined} aria-describedby={described('item', true)}
          onChange={(e) => set('item', e.target.value)} onBlur={() => setTouched((t) => ({ ...t, item: true }))} />
        {show('item') ? <p id={id('item-err')} className={styles.error}>{errors.item}</p> : null}
      </div>

      <fieldset className={styles.field}>
        <legend className={styles.label}>What kind of thing is it?</legend>
        <div className={styles.choices}>
          {[...CATEGORIES, 'Something else'].map((c) => (
            <label key={c} className={styles.choice}>
