}
.kicker { margin: 0 0 18px; font-family: var(--s3-font-mono); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mm-saffron); }
.headline { --s3-ink: var(--mm-thread); }
/* Size the composed recipe's heading for a campaign hero (its own clamp tops out at 9cqi). */
.headline h2 { font-size: clamp(2.6rem, 1.4rem + 7cqi, 5.25rem); font-weight: 800; }
.lede { margin: 20px 0 0; max-width: 46ch; font-size: 1.0625rem; line-height: 1.55; color: var(--mm-thread-muted); text-wrap: pretty; }
.when {
  display: flex; flex-wrap: wrap; gap: 12px 36px; margin: 26px 0 0; padding-top: 16px;
