@container (min-width: 60rem) { .pledgeGrid { grid-template-columns: minmax(0, 1fr) minmax(0, 0.92fr); gap: 56px; align-items: start; } }
.form, .done { display: grid; gap: 22px; padding: 20px; background: var(--s3-surface); border: 1px solid var(--s3-line); }
