.raceRow[data-lead] .raceName { font-weight: 700; }
.raceTrack { position: relative; grid-area: bar; height: 12px; overflow: hidden; background: var(--s3-surface-2); }
.raceBar { position: absolute; inset: 0; background: var(--mm-indigo); transform-origin: left center; transition: transform var(--s3-duration-slow) var(--s3-ease-emphasized); }
.raceRow[data-lead] .raceBar { background: var(--mm-saffron); }
.raceValue { grid-area: value; font-family: var(--s3-font-mono); font-size: 0.875rem; font-variant-numeric: tabular-nums; text-align: right; }

.footer { margin-top: 56px; padding-top: 18px; border-top: 2px dashed var(--mm-stitch); font-size: 0.875rem; line-height: 1.55; color: var(--s3-ink-muted); }
.footer p { margin: 0 0 6px; max-width: 70ch; }
